#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    long long minMergedInteger(std::vector<int>& nums) {
        long long ans = 9e18;
        for (int i = 0; i < (int)nums.size(); i += 2) {
            std::string s = std::to_string(nums[i]) + std::to_string(nums[i + 1]);
            long long val = std::stoll(s);
            ans = std::min(ans, val);
        }
        return ans;
    }
};

class Solution {
    public int minMergedInteger(int[] nums) {
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length; i += 2) {
            int merged = Integer.parseInt("" + nums[i] + nums[i + 1]);
            ans = Math.min(ans, merged);
        }
        return ans;
    }
}

var minMergedInteger = function(nums) {
    let ans = Infinity;
    for (let i = 0; i < nums.length; i += 2) {
        const merged = parseInt(`${nums[i]}${nums[i + 1]}`, 10);
        ans = Math.min(ans, merged);
    }
    return ans;
};
